const authError = (code, detail) => ({
    statusCode: 401,
    headers: { 'Content-Type': 'application/json', 'WWW-Authenticate': 'Bearer error="' + code + '"' },
    payload: { detail }
});

const mode = String(env.get('AI_INSIGHT_AUTH__MODE') || 'enforce').toLowerCase();
msg._authMode = mode;
if (mode === 'off') {
    msg.identity = null;
    msg.authRejected = false;
    node.warn('ai-insight-auth: AI_INSIGHT_AUTH__MODE=off — header-derived roles (dev only)');
    return [null, null, msg];
}

const authHeader = (msg.req && msg.req.headers && msg.req.headers.authorization) || '';
const m = /^Bearer\s+(.+)$/i.exec(authHeader.trim());
if (!m) {
    Object.assign(msg, authError('missing_authorization', 'Authorization: Bearer <access token> is required'));
    msg.identity = null;
    msg.authRejected = true;
    return [null, null, msg];
}
const token = m[1];

let header;
let payload;
try {
    const parts = token.split('.');
    if (parts.length !== 3) throw new Error('not a JWS');
    header = JSON.parse(Buffer.from(parts[0], 'base64url').toString('utf8'));
    payload = JSON.parse(Buffer.from(parts[1], 'base64url').toString('utf8'));
} catch (e) {
    Object.assign(msg, authError('invalid_token', 'malformed bearer token'));
    msg.identity = null;
    msg.authRejected = true;
    return [null, null, msg];
}

const issuer = env.get('AI_INSIGHT_AUTH__ISSUER') || env.get('FACIS_KEYCLOAK_URL') || 'https://identity.facis.cloud/realms/facis';
if (payload.iss !== issuer) {
    Object.assign(msg, authError('invalid_token', 'unexpected token issuer'));
    msg.identity = null;
    msg.authRejected = true;
    return [null, null, msg];
}

msg._authToken = token;
msg._authKid = header.kid || null;
msg._authIssuer = issuer;
msg._authOrigPayload = msg.payload;

const ttlMs = Math.max(60, Number(env.get('AI_INSIGHT_AUTH__JWKS_TTL_SECONDS') || 300)) * 1000;
const cache = global.get('aiInsightAuthJwksCache');
const kidInCache = cache && Array.isArray(cache.keys)
    && (!msg._authKid || cache.keys.some((k) => k.kid === msg._authKid));
if (cache && (Date.now() - cache.fetchedAt) < ttlMs && kidInCache) {
    msg._authJwks = { keys: cache.keys };
    return [msg, null, null];
}

msg.url = env.get('AI_INSIGHT_AUTH__JWKS_URL') || (issuer + '/protocol/openid-connect/certs');
msg._authJwksFetched = true;
return [null, msg, null];

// jose is in scope from this node's own libs declaration
// (functionExternalModules injects it as a bound variable).
(async () => {
    const authError = (code, detail) => ({
        statusCode: 401,
        headers: { 'Content-Type': 'application/json', 'WWW-Authenticate': 'Bearer error="' + code + '"' },
        payload: { detail }
    });
    try {
        let jwksDoc;
        if (msg._authJwksFetched) {
            const status = Number(msg.statusCode || 0);
            jwksDoc = msg.payload;
            if (status !== 200 || !jwksDoc || !Array.isArray(jwksDoc.keys)) {
                msg.statusCode = 503;
                msg.headers = { 'Content-Type': 'application/json' };
                msg.payload = { detail: 'Authorization server unavailable (JWKS fetch failed)' };
                msg.identity = null;
                msg.authRejected = true;
                node.send(msg);
                return;
            }
            global.set('aiInsightAuthJwksCache', { keys: jwksDoc.keys, fetchedAt: Date.now() });
        } else {
            jwksDoc = msg._authJwks;
        }

        msg.payload = msg._authOrigPayload;

        const kid = msg._authKid;
        const jwk = jwksDoc.keys.find((k) => !kid || k.kid === kid);
        if (!jwk) {
            Object.assign(msg, authError('invalid_token', 'unknown signing key'));
            msg.identity = null;
            msg.authRejected = true;
            node.send(msg);
            return;
        }

        const key = await jose.importJWK(jwk, jwk.alg || 'RS256');
        const opts = { issuer: msg._authIssuer, clockTolerance: 5 };
        const audience = env.get('AI_INSIGHT_AUTH__AUDIENCE');
        if (audience) opts.audience = audience;

        const verified = await jose.jwtVerify(msg._authToken, key, opts);
        const claims = verified.payload;
        const roles = (claims.realm_access && Array.isArray(claims.realm_access.roles))
            ? claims.realm_access.roles
            : [];
        msg.identity = {
            sub: claims.sub || null,
            username: claims.preferred_username || null,
            client: claims.azp || null,
            roles,
            verifiedAt: new Date().toISOString()
        };
        msg.authRejected = false;
        delete msg.statusCode;
    } catch (e) {
        if (e && e.code === 'ERR_JWT_EXPIRED') {
            Object.assign(msg, authError('token_expired', 'access token expired'));
        } else if (e && e.code === 'ERR_JWT_CLAIM_VALIDATION_FAILED') {
            Object.assign(msg, authError('invalid_token', 'token claim validation failed: ' + (e.claim || 'unknown')));
        } else {
            Object.assign(msg, authError('invalid_token', 'token signature verification failed'));
        }
        msg.identity = null;
        msg.authRejected = true;
    }
    delete msg._authToken;
    delete msg._authKid;
    delete msg._authIssuer;
    delete msg._authJwks;
    delete msg._authJwksFetched;
    delete msg._authOrigPayload;
    node.send(msg);
    node.done();
})();
return;
